// Low-poly island, animated faceted water and a 20 second day/night cycle.
// ?hour=14 freezes the clock for a capture.
const DAY_SECONDS = 20;
const START_HOUR = 9;
const fixedHourParam = new URLSearchParams(location.search).get("hour");
